<template><div><section class="pro-panel"><span class="eyebrow">Performance intelligence</span><h1>Analytics</h1><p>Understand your published record using the figures currently stored on your tipster profile.</p></section><section class="td-kpis"><div class="td-kpi"><span>Total tips</span><b>{{tipster?.totalTips||0}}</b><small>published selections</small></div><div class="td-kpi"><span>Win rate</span><b>{{winRate}}%</b><small>{{tipster?.wins||0}} wins · {{tipster?.losses||0}} losses</small></div><div class="td-kpi"><span>Longest streak</span><b>{{tipster?.longestStreak||0}}</b><small>consecutive wins</small></div><div class="td-kpi"><span>ROI</span><b>{{formatPercent(tipster?.roi)}}</b><small>recorded return</small></div></section><div class="td-grid"><section class="pro-panel"><h2>Record breakdown</h2><div class="td-mini-stats"><div><span>Wins</span><b>{{tipster?.wins||0}}</b></div><div><span>Losses</span><b>{{tipster?.losses||0}}</b></div><div><span>Current streak</span><b>{{tipster?.currentStreak||0}}</b></div><div><span>Profit</span><b>{{formatProfit(tipster?.profit)}}</b></div></div></section><section class="pro-panel"><h2>Recent settled tips</h2><div v-if="settled.length" class="td-table"> <div v-for="p in settled.slice(0,8)" :key="p._id" class="td-table-row"><div><b>{{p.fixture||'Football match'}}</b><small>{{p.prediction}}</small></div><strong>{{Number(p.odds||0).toFixed(2)}}</strong><em :class="'td-status-pill '+p.status">{{p.status}}</em></div></div><div v-else class="empty">Settled performance data will appear here.</div></section></div></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api}from'../services/api';import{formatPercent,formatProfit}from'../utils/formatters';const tipster=ref<any>(null),predictions=ref<any[]>([]);const settled=computed(()=>predictions.value.filter(x=>['won','lost','void'].includes(x.status)));const winRate=computed(()=>{const w=Number(tipster.value?.wins||0),l=Number(tipster.value?.losses||0);return w+l?Math.round(w/(w+l)*100):0});onMounted(async()=>{try{const d=await api.get('/me/tipster');tipster.value=d.data.profile;predictions.value=d.data.predictions||[]}catch{}})</script>
